entries[163121] = { ["name"] = "Boshafter Kriegsbasilisk", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren boshaften Kriegsbasilisken oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sein Atem ist schlimmer als sein Biss.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
