entries[163181] = { ["name"] = "P'terrorflügel des Feuerlords", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 * 20 / 5) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Möge das Aroma Euch läutern!\"\nVerkaufspreis:" }
