entries[163183] = { ["name"] = "Grüner Sumpfhüpfer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren grünen Sumpfhüpfer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Habse sammelt überall in den Froschmarschen die Sprosse von Krag'wa, doch nur die bauchigsten werden als Reittiere verwendet.\"\nVerkäufer:\nHabse\nZone:\nNazmir\nKosten:" }
entries[163184] = { ["name"] = "Außenpostenausbau", ["text"] = "Baut Euren Außenposten an der Steinfaustwache im Tiragardesund aus." }
entries[163185] = { ["name"] = "Missionsbericht", ["text"] = "Questgegenstand\n\"Enthält Details über die Mission, geborgene Materialien für die Steinfaustwache zu sichern.\"" }
entries[163186] = { ["name"] = "Feuriger Pegasus", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen feurigen Pegasus oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese fliegenden Wesen galoppieren für gewöhnlich unbemerkt durch den Himmel. Welch ein Glück, dass dieses sich Euch gezeigt hat!\"\nPromotion:\nJubiläum von Hearthstone" }
entries[163187] = { ["name"] = "Abgrundbitter", ["text"] = "Benutzen: Ein extrem starkes alkoholisches Getränk.\n\"Gebraut in der kalten, dunklen Leere der Tiefen.\"\nVerkaufspreis:" }
