entries[163189] = { ["name"] = "Eimer Mondbrunnenwasser", ["text"] = "Questgegenstand\nBenutzen: Löscht die Flammen.\n\"Kann an jeder nahen Wasserquelle aufgefüllt werden.\"" }
entries[163190] = { ["name"] = "Außenpostenausbau", ["text"] = "Baut Euren Außenposten an der Steinhauerwacht im Sturmsangtal aus." }
