entries[163192] = { ["name"] = "Leviathantränen", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Eine Spirituose, die 18 Jahre lang an Orten gereift ist, die das Licht nicht erreichen kann. Kein Leviathan ist während der Herstellung dieses Produkts zu Schaden gekommen.\"\nVerkaufspreis:" }
