entries[163194] = { ["name"] = "Missionsbericht", ["text"] = "Questgegenstand\n\"Enthält Details über die Mission zur Beschaffung von Informationen für die Druiden der Flinkwindstation.\"" }
entries[163195] = { ["name"] = "Bauplan: Improvisierter Azeritdetektor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen improvisierten Azeritdetektor herstellt.\nStellt einen improvisierten Azeritdetektor her.\nBenötigt Ingenieurskunst von Kul Tiras (50)\nVerkaufspreis:\nImprovisierter Azeritdetektor\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with a Makeshift Azerite Detector which grants:Chance to bring back Azerite from successful missions.\nVerkaufspreis:\nBenötigt Platinerz (50), Isoliertes Kabel (25), Chemische Sprengkapsel (3), Expulsom (50), Hydrokern (5), Hypersensibler Azeritometersensor" }
entries[163196] = { ["name"] = "Fläschchen der Unsichtbarkeit", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Macht Euch für so gut wie alles unsichtbar. (5 Sek. Abklingzeit)" }
