entries[163200] = { ["name"] = "Verfluchtes Fernglas", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schaut in die Ferne und seht nach, was diese räudige Bande im Schilde führt! (15 Min Abklingzeit)\nBenötigt Prachtmeeradmiralität\n- Respektvoll" }
entries[163201] = { ["name"] = "Gnollzielfass", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört ein Gnollzielfass am Zielort, das für 5 Min. bestehen bleibt. Während es aufgestellt ist, dient das Fass als Zielattrappe.\n\nKann nur im Freien in Kul Tiras und Zandalar eingesetzt werden. (30 Min Abklingzeit)\nBenötigt Prachtmeeradmiralität\n- Wohlwollend" }
entries[163202] = { ["name"] = "Haibiss", ["text"] = "Benutzen: Ein extrem starkes alkoholisches Getränk.\n\"Eine Kombination aus feinsten Rumsorten, reifsten Früchten und einer Prise unserer Geheimzutat, die einen gewissen Biss beisteuert! Grrr!\"\nVerkaufspreis:" }
entries[163203] = { ["name"] = "Hypersensibler Azeritometersensor", ["text"] = "Handwerksmaterial\n\"Wird dieser Sensor in ein Gerät integriert, können mit ihm kleinste Spuren von Azerit mehrere Meter unterhalb des Bodens aufgespürt werden. Kann bei Händlern erworben oder verkauft werden.\"\nVerkaufspreis:" }
entries[163205] = { ["name"] = "Geisterhaftes Leckerli", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Oh nein! Hat Euer Haustier den Schleier durchbrochen?\nBenötigt Glutorden\n- Wohlwollend\nVerkaufspreis:" }
entries[163207] = { ["name"] = "Grals Rachenputzer", ["text"] = "Benutzen: Ein typisches alkoholisches Getränk.\n\"Ein selbstgebrautes SHB. Ein sehr helles Bier für den anspruchslosen Biertrinker... mit einem Nachgeschmack von Niedrigwasser.\"\nVerkaufspreis:" }
