entries[163210] = { ["name"] = "Partytotem", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt das Mojo zum Fließen. (5 Min Abklingzeit)\nBenötigt Zandalariimperium\n- Respektvoll" }
entries[163211] = { ["name"] = "Akundas Feuerstab", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Baut ein Lagerfeuer und benutzt Akundas Feuerstab, um einen Funken zu erzeugen. Das Feuer erhöht die Vielseitigkeit von jedem in der Nähe um 1 und ermöglicht das Kochen. (5 Min Abklingzeit)\nBenötigt Voldunai\n- Wohlwollend" }
entries[163212] = { ["name"] = "Reinigender Weihrauchschwenker", ["text"] = "Questgegenstand\nBenutzen: Schwingt den Weihrauchschwenker und läutert Verderbnisquellen in der Nähe." }
entries[163213] = { ["name"] = "Geisterhafter Entdeckerschädel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Schädel auf dem Boden, damit er den tollen Ort sehen kann, an dem Ihr seid. (5 Min Abklingzeit)\nBenötigt Voldunai\n- Respektvoll\n\"Vom vorherigen Besitzer wird eine Anzahlung verlangt.\"" }
