entries[163215] = { ["name"] = "Schriftrolle der explosiven Kleintiere", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Liest eine magische Schriftrolle, um Kleintiere in der Nähe zu vernichten. (5 Sek. Abklingzeit)\nBenötigt Tortollanische Sucher\n- Wohlwollend\nVerkaufspreis:" }
entries[163216] = { ["name"] = "Blutgesättigter Krogg", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren blutgesättigten Krogg oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Krogg wurde allein zurückgelassen, um sich an G'huuns verderbtem Blut zu laben und vor sich hin zu faulen. Er hätte nicht glücklicher sein können.\"\nErfolg:\nRuhm des Schlachtzüglers von Uldir\nKategorie:\nDungeons & Schlachtzüge" }
