entries[163562] = { ["name"] = "Pestrufers Sterbefix", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Der einfachste Ausweg.\n\nWARNUNG: Wird Euch töten. (3 Min Abklingzeit)\n\"Eine zugepfropfte Phiole mit einer blassen, unregelmäßig herumwirbelnden Flüssigkeit. Auf dem Etikett ist ein Schädel abgebildet.\"" }
entries[163563] = { ["name"] = "Urzeitliche Wassermelone", ["text"] = "Benutzen: Bietet dieses Futter einem Brutosaurus in der Nähe an.\n\"Obwohl für die meisten Kreaturen ungenießbar, lieben die Brutosaurier in Nazmir diese Frucht.\"\nVerkaufspreis:" }
entries[163564] = { ["name"] = "Besonders trockenes Früchtebrot", ["text"] = "Einzigartig\nBenutzen: Bietet dieses Futter einem Brutosaurus in der Nähe an.\n\"Wie aus den Brutosauriern in Zuldazar solche Naschkatzen wurden, ging in den Nebeln der Zeit und Legenden verloren.\"\nVerkaufspreis:" }
entries[163567] = { ["name"] = "Schlange am Spieß", ["text"] = "Einzigartig\nBenutzen: Bietet dieses Futter einem Brutosaurus in der Nähe an.\n\"Brutosaurier sind in Vol'dun selten. Noch seltener sind fleischfressende Brutosaurier. Am seltensten sind aber Brutosaurier, die ihr Fleisch gebraten mögen.\"\nVerkaufspreis:" }
entries[163568] = { ["name"] = "Verschollener Schnabelsaurus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man den verschollenen Schnabelsaurus beschwört.\nMit Rechtsklick Euren verschollenen Schnabelsaurus beschwören oder wieder freigeben.\n80 ( 80)" }
