entries[163570] = { ["name"] = "Außenpostenausbau", ["text"] = "Baut Euren Außenposten an der Flinkwindstation in Drustvar aus." }
entries[163571] = { ["name"] = "Außenpostenausbau", ["text"] = "Baut Euren Außenposten am Geiernest in Vol'dun aus." }
entries[163572] = { ["name"] = "Missionsbericht", ["text"] = "Questgegenstand\n\"Enthält Details über die Mission, die Vorräte für das Geiernest in Vol'dun zu bergen.\"" }
entries[163573] = { ["name"] = "Goldmähnes Zügel", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Goldmähne beschwört.\nBeschwört Goldmähne oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Lord Sturmsang befahl seinen Handlangern, dieses Pferd vom Anwesen der Norwinsens in Tiragarde zu stehlen, da er seine herrliche goldene Mähne begehrte.\"\nZone:\nSturmsangtal" }
entries[163574] = { ["name"] = "Durchgekaute Zügel des verängstigten Packmulis", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein verängstigtes Packmuli beschwört.\nBeschwört Euer verängstigtes Packmuli oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Dieses arme Muli befand sich in Drustvar, als die Hexen dort die Herrschaft an sich rissen. Es hat schon zu viel miterlebt.\"\nZone:\nDrustvar" }
entries[163575] = { ["name"] = "Zügel eines gezähmten Blutschmausers", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen springenden Venensucher beschwört.\nBeschwört Euren springenden Venensucher oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sprühmittel gegen Insekten und ein Hut mit Netz werden Euch in den Sümpfen von Nazmir nicht weiterhelfen. Nehmt eine Keule mit.\"\nZone:\nNazmir" }
entries[163576] = { ["name"] = "Gefangener Dünenaasfresser", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Dünenaasfresser beschwört.\nBeschwört Euren Dünenaasfresser oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese widerstandsfähigen Aasfresser können in der Ödnis von Vol'dun monatelang mit wenig Nahrung und Wasser überleben.\"\nZone:\nVol'dun" }
entries[163577] = { ["name"] = "Sensenschlund des Eroberers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Sensenschlund des Eroberers oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der kampfgehärtete Panzer dieser mächtigen Bestie kann selbst den wuchtigsten Hammer und den schärfsten Speer ablenken.\"\nErfolg:\nEroberer von Azeroth\nKategorie:\nWelt" }
entries[163578] = { ["name"] = "Gezähmter Hochlandmustang", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren gezähmten Hochlandmustang oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eins der Rösser aus Arathi. Die Horde nahm es nach der Eroberung von Burg Stromgarde gefangen und brach seinen Willen.\"\nBeute von:\nKürassier Aldrin\nZone:\nDas Arathihochland" }
entries[163579] = { ["name"] = "Hochlandmustang", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Hochlandmustang oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein tapferes Ross des Arathihochlands, das keine Furcht kennt.\"\nBeute von:\nVerdammnisreiter Helgrim\nZone:\nDas Arathihochland" }
entries[163580] = { ["name"] = "Zerbrechliches Modell der Kathedrale des Lichts", ["text"] = "\"Aus gefaltetem Papier gefertigt, das mit poetischen Texten beschrieben ist.\"\nVerkaufspreis:" }
entries[163581] = { ["name"] = "Fragile Nachbildung von Burg Sturmwind", ["text"] = "\"Aus gefaltetem Papier gefertigt, das mit poetischen Texten beschrieben ist.\"\nVerkaufspreis:" }
entries[163582] = { ["name"] = "Qinshos ewiger Hund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Qinshos ewigen Hund oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Qinsho schuf diesen ewigen Wächter aus purem Gold und gewährte ihm die Widerstandskraft der Erde.\"\nBeute von:\nInselexpeditionen" }
entries[163583] = { ["name"] = "Klippenhornspringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Klippenhornspringer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese mächtigen Springer haben sich an das Leben auf Inseln angepasst, indem sie Möwen erbeuten, die versuchen, Nahrung aus Felswänden oder Felsspalten zu picken.\"\nBeute von:\nInselexpeditionen" }
entries[163584] = { ["name"] = "Zwielichträcher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Zwielichträcher oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur wenig ist über das Schicksal des Zwielichtdrachenschwarms bekannt, doch in Grim Batol scheint es bis heute Scharen dieser Drachen zu geben.\"\nBeute von:\nInselexpeditionen" }
entries[163585] = { ["name"] = "Gischtqualle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare Gischtqualle oder gibt sie wieder frei.\n\nLässt sich nur unter Wasser einsetzen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wer gestochen wird, hat so wenig Zeit, bevor er umwickelt und verschlungen wird, dass man sich wirklich überlegen sollte, nicht im Großen Meer zu schwimmen.\"\nBeute von:\nInselexpeditionen" }
entries[163586] = { ["name"] = "Krächz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Krächz oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ratet mal, woher der Name kommt. Den hat er nicht, weil er so ein ruhiges, possierliches Tierchen ist.\"\nBeute von:\nInselexpeditionen" }
