entries[163589] = { ["name"] = "Zügel des fahlen Terrorhorns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man ein fahles Terrorhorn beschwört.\nBeschwört Euer reitbares fahles Terrorhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Hellhäutige Terrorhörner sind recht selten, was den Preis rechtfertigt.\"\nVerkäufer:\nTalutu\nZone:\nZuldazar\nKosten:\n500.\n\nVerkäufer:\nDer ausgefuchste Nick\nZone:\nDer Tiragardesund\nKosten:\n500." }
