entries[163637] = { ["name"] = "Eisenschmieder Alt", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Ein alter zwergischer Verschnitt, der aus über Schmiedefeuern gemalzter Gerste destilliert wird.\"\nVerkaufspreis:" }
entries[163638] = { ["name"] = "12 Jahre alter Korlach Edel", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Dieser in der Tradition der Whiskys aus Drustvar hergestellte Tropfen wurde in Fassstärke abgefüllt und ist notfalls auch hochentzündlich.\"\nVerkaufspreis:" }
entries[163639] = { ["name"] = "Uralter fassgereifter Arathorwhisky", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Diese Spirituose wurde aus dem einzigen Fass abgefüllt, das aus dem Reich Arathor noch verblieben war. Ihr Alter lässt sich unmöglich schätzen.\"\nVerkaufspreis:" }
entries[163640] = { ["name"] = "Klarer Huangtzewhisky", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Ein delikates Tröpfchen aus dem Tal der Vier Winde. Seine einzigartigen Geschmacksnoten werden angeblich einzig durch das vom Grund der Huangtzekaskade gesammelte Wasser erzielt.\"\nVerkaufspreis:" }
entries[163641] = { ["name"] = "Kristallklarer Brunnhildar", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Diese aus im Holzofen gebranntem Getreide destillierte Spirituose bietet nach einem einzigartigen Kaltfiltrierverfahren eine Balance aus reinem Malz und Rauch.\"\nVerkaufspreis:" }
entries[163642] = { ["name"] = "Der Horst, 8 Jahre, Hinterlandwhisky", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Eine Spirituose von ungezähmtem Charakter, der seine grasige Note einem Wildgetreide verdankt, das nur nahe der Gipfel der Hinterlandberge wächst.\"\nVerkaufspreis:" }
entries[163643] = { ["name"] = "25 Jahre in Runenholz gereifter Haustvalder", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Die magischen Eigenschaften des Runenwaldes verleihen diesem Vrykulgetränk einen wahrhaft einzigartigen Abgang.\"\nVerkaufspreis:" }
entries[163644] = { ["name"] = "Schneller Albinoraptor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren schnellen Albinoraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bestienreiter Kama, ein Krieger der Bleichborken, schlug einst auf so einem Ungeheuer eine blutige Schneise des Schreckens durch das gesamte Arathihochland.\"\nBeute von:\nBestienreiter Kama\nZone:\nDas Arathihochland" }
entries[163645] = { ["name"] = "Schädelreißer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Schädelreißer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein cleveres Kerlchen.\"\nBeute von:\nZone:\nDas Arathihochland" }
entries[163646] = { ["name"] = "Eselchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Eselchen oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser vermutlich aus Neuhof im Arathihochland gestohlene tapfere Esel war dazu bestimmt, von Kobolden gefressen zu werden.\"\nBeute von:\nAufseher Krix\nZone:\nDas Arathihochland" }
entries[163647] = { ["name"] = "Azeritsplitter", ["text"] = "Questgegenstand\n\"Der sehr kleine Erzklumpen leuchtet vor unbegreiflicher Macht.\"" }
entries[163648] = { ["name"] = "Flauschiger Kriechling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren flauschigen Kriechling beschwören oder wieder freigeben.\n80 ( 80)" }
