entries[163651] = { ["name"] = "Wurstmartini", ["text"] = "Benutzen: Ein typisches alkoholisches Getränk.\n\"Herzhaft und süß. Der Geschmack von Äpfeln und feiner Wurst aus Drustvar mit einer rauchigen Note. Eigentlich nicht möglich, aber es funktioniert trotzdem. Garniert mit einer Miniwurst.\"\nVerkaufspreis:" }
