entries[163677] = { ["name"] = "Titanenkügelchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[163678] = { ["name"] = "Nad el Kissens Pfähler", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n11 - 22 Schaden Geschwindigkeit 3.60\n(4.6 Schaden pro Sekunde)\n+6 Beweglichkeit\n+9 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nErhöht Eure Tempowertung um + 5.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[163679] = { ["name"] = "Severus' Bindungen", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Stoff\n3 Rüstung\n+4 Intelligenz\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[163680] = { ["name"] = "Seuchenbefallene Schritte", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\n+ 5 Vielseitigkeit\nHaltbarkeit 65 / 65\nVerkaufspreis:" }
