entries[163685] = { ["name"] = "Abgenutzte Schatzkarte", ["text"] = "\"Beim zweiten Mal nicht mehr ganz so nützlich.\"\nVerkaufspreis:" }
entries[163686] = { ["name"] = "Eine doppelte Augenklappe", ["text"] = "\"War zuletzt im Besitz eines der unfähigsten Navigatoren der Eisenfluträuber.\"\nVerkaufspreis:" }
entries[163687] = { ["name"] = "Grässlich geschriebenes Seemannslied", ["text"] = "\"Der Beweis, dass betrunkene Seemänner sich aufs Singen beschränken sollten.\"\nVerkaufspreis:" }
entries[163688] = { ["name"] = "Eine Holzhand", ["text"] = "\"Ein klein wenig weniger funktionell als ein Holzbein.\"\nVerkaufspreis:" }
entries[163689] = { ["name"] = "Wütendes Ei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
