entries[163691] = { ["name"] = "Brennende Essenz", ["text"] = "Benutzen: Ruft einen Verbündeten herbei, der Euch 10 Min. lang im Kampf unterstützt. Ihr müsst Euch im Arathihochland befinden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[163692] = { ["name"] = "Schriftrolle des Lebensunterhalts", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 10000 / 5 * 20) Gesundheit und ( 6000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Bitte den Zauberspruch aufsagen, nicht direkt konsumieren. Das Pergament bietet keinerlei Nährwert.\"\nVerkaufspreis:" }
entries[163693] = { ["name"] = "Fragment des Geschmolzenen Kerns", ["text"] = "Questgegenstand\n\"Ein kleines Fragment des Geschmolzenen Kerns.\"" }
entries[163694] = { ["name"] = "Schriftrolle des genüsslichen Rückrufs", ["text"] = "Benutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Das Leben muss man genießen.\"\nVerkaufspreis:" }
entries[163695] = { ["name"] = "Schriftrolle der inneren Wahrheit", ["text"] = "Benutzen: Die Geheimnisse des Universums offenbaren sich nur zu jenen, die zuhören.\nVerkaufspreis:" }
entries[163697] = { ["name"] = "Laserpointer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Richtet einen Laserpointer auf den Boden. Vielleicht wird etwas ihn jagen. (2 Min Abklingzeit)" }
entries[163698] = { ["name"] = "Donnernde Essenz", ["text"] = "Benutzen: Ruft einen Verbündeten herbei, der Euch 10 Min. lang im Kampf unterstützt. Ihr müsst Euch im Arathihochland befinden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[163699] = { ["name"] = "Ausgehärtetes Honigamulett", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Auf der Hinterseite des Amuletts ist der Name Rosalina Mildenhall eingraviert.\"" }
entries[163700] = { ["name"] = "Schäumende Essenz", ["text"] = "Benutzen: Ruft einen Verbündeten herbei, der Euch 10 Min. lang im Kampf unterstützt. Ihr müsst Euch im Arathihochland befinden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[163701] = { ["name"] = "Bebende Essenz", ["text"] = "Benutzen: Ruft einen Verbündeten herbei, der Euch 10 Min. lang im Kampf unterstützt. Ihr müsst Euch im Arathihochland befinden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[163702] = { ["name"] = "Rosalinas Brief", ["text"] = "Questgegenstand\nEinzigartig\n\"Auf der Vorderseite des Umschlags steht in wundervoll geschwungener Schrift 'Lieber Anselm'.\"" }
entries[163703] = { ["name"] = "Kroggzerkauter Oberschenkelknochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 9.\nAnlegen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, einen großen Knochen nach Eurem Ziel zu werfen, der 33 Schaden verursacht.\nVerkaufspreis:" }
entries[163704] = { ["name"] = "Winzige mechanische Maus", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt eine kleine Robomaus ab, die Euer Haustier 30 Sek. lang jagen kann. (5 Min Abklingzeit)" }
entries[163705] = { ["name"] = "Eingebildete Kanone", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schießt mit einer eingebildeten Kanone auf Euer Haustier, wodurch es sich für 10 Sek. totstellt. (3 Min Abklingzeit)" }
entries[163706] = { ["name"] = "Düsterschwinge der Bleichborken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es gibt im Arathihochland nur noch eine Handvoll dieser Riesenfledermäuse, die von den Bleichborkenwaldtrollen ursprünglich hierhergebracht und sorgsam von ihnen aufgezogen wurden.\"\nBeute von:\nNimar der Töter\nZone:\nDas Arathihochland" }
entries[163707] = { ["name"] = "Rolle der Schnelligkeit von Torga", ["text"] = "Benutzen: Erhaltet den Segen der Schnelligkeit von Torga.\nVerkaufspreis:" }
entries[163708] = { ["name"] = "Eisenfeind", ["text"] = "Questgegenstand\n\"Dieser Hammer wurde von Franclorn Schmiedevater geschmiedet und hat schon unzählige Male den Besitzer gewechselt.\"\nVerkaufspreis:" }
entries[163709] = { ["name"] = "Kurbeltuffs Gebräu", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk." }
entries[163710] = { ["name"] = "Kaufmannsschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Wurde der armen Seele von einem hungrigen Raben gestohlen.\"" }
entries[163711] = { ["name"] = "Splitter von Fozruk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[163712] = { ["name"] = "Manaverformtes Ei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[163713] = { ["name"] = "Kohlenpfannenkappe", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert eine kleine Kohlenpfanne auf Eurem Kopf. (1 Stunde Abklingzeit)\n\"Ihr habt Kohlenpfanne genommen.\"" }
entries[163714] = { ["name"] = "Verbotenes Seemannslied der munteren Meute", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Liedzeilen sollen die Mannschaft aufheitern und sie zu reger Arbeit motivieren, aber es ist offensichtlich, dass keiner von ihnen mehr am Leben ist.\"\nVerkaufspreis:" }
entries[163715] = { ["name"] = "Verbotenes Seemannslied des Früchtezählens", ["text"] = "Wird beim Aufheben gebunden\n\"Zunächst klingt es wie das Lied eines einfachen Hafenarbeiters, doch dann wird Euch klar, dass dieser Arbeiter der Tod ist, der Seelen einsammelt und sich das Ende seiner eigenen Existenz herbeisehnt.\"\nVerkaufspreis:" }
entries[163716] = { ["name"] = "Verbotenes Seemannslied des Zechens", ["text"] = "Wird beim Aufheben gebunden\n\"Beim Zuhören denkt man zunächst, dieses Seemannslied handle von einer Besatzung, die einem betrunkenen Besatzungsmitglied einige lustige Streiche spielt. Aber je länger man über den Text nachdenkt, desto verstörender wird er.\"\nVerkaufspreis:" }
entries[163717] = { ["name"] = "Verbotenes Seemannslied des Josephus", ["text"] = "Wird beim Aufheben gebunden\n\"Der Text dieses Seemannsliedes erzählt von einem Seemann, der offenbar unter dem Namen 'Joe' bekannt war, und von seinen widerlichen Erlebnissen in einer Hafenstadt.\"\nVerkaufspreis:" }
entries[163718] = { ["name"] = "Verbotenes Seemannslied der schwarzen Kugel", ["text"] = "Wird beim Aufheben gebunden\n\"Der Text dieses Seemannsliedes beschreibt die grausame Behandlung von Seeleuten durch einen Kapitän namens Schwarzkugel Bill.\"\nVerkaufspreis:" }
entries[163719] = { ["name"] = "Verbotenes Seemannslied des Gauls", ["text"] = "Wird beim Aufheben gebunden\n\"Der Text dieses Seemannsliedes kündet vom unausweichlichem Tod eines geschundenen Pferdes.\"\nVerkaufspreis:" }
entries[163720] = { ["name"] = "Zuchtformel von Mildenhall", ["text"] = "Questgegenstand\nBenutzen: Füttert Hummelbummel.\n\"Riecht leicht nach Honig, Lavendel und faulen Eiern.\"" }
