entries[163731] = { ["name"] = "Tuch des gefürchteten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\nBenötigt eine Allianz-Rasse\nVerkaufspreis:" }
