entries[163734] = { ["name"] = "Prall gefüllter Geldbeutel", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[163735] = { ["name"] = "Faulbauch", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stößt ein lautes, störendes Geräusch aus, das alle Ziele innerhalb von 10 Metern erschreckt. (5 Min Abklingzeit)\n\"Für zivilisierte Gesellschaft ungeeignet.\"" }
entries[163736] = { ["name"] = "Geisterhafte Erscheinung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nehmt eine geisterhafte Erscheinung an. (1 Stunde Abklingzeit)\n\"Wenn man sich selbst wie tot fühlt.\"" }
entries[163738] = { ["name"] = "Maske des Syndikats", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Legt anstelle Eurer aktuellen Kopfbedeckung eine Maske des Syndikats an. (1 Stunde Abklingzeit)\n\"Riecht leicht nach Pfefferminzbonbons und Mord, den zwei Dingen, die die Sängerin am liebsten mag.\"" }
entries[163739] = { ["name"] = "Legend'n der Loa: Torcali", ["text"] = "Wird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>" }
entries[163740] = { ["name"] = "Ritualmesser der Drust", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Führt eine rituelle Opferung durch, die die Seele des Ziels den Drust darbietet. Kann nur auf kürzlich Verstorbene angewandt werden. (1 Min Abklingzeit)" }
entries[163741] = { ["name"] = "Magischer Spaßstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Wirft den Stein einem freundlich gesinnten Spielercharakter zu. Wenn möglich, wirft er ihn automatisch zurück. (30 Sek. Abklingzeit)\n\"Der NEUE lustige Spaßstein, jetzt mit 100% mehr GLITZER!\"" }
entries[163742] = { ["name"] = "Herzbannzauberfoliant", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Unterwirft den Benutzer dem Zauber des Herzbannzirkels.\n\"Voller verbotener Zaubersprüche und Tricks des Herzbannzirkels.\"" }
entries[163743] = { ["name"] = "Drustseelenfänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Aktiviert den Seelenfänger und ermöglicht es dem Träger, mit 20% Gesundheit und Mana wiederbelebt zu werden. Kann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (1 Stunde Abklingzeit)\n20 Aufladungen" }
entries[163744] = { ["name"] = "Frostzorns Kühlbox", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ruft einen leichten Schneefall hervor. (10 Min Abklingzeit)\n\"Kor'gesh hat sie irgendwo verstaut.\"" }
entries[163745] = { ["name"] = "Gong der Bleichborken", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert einen Waldtrollgong. (5 Min Abklingzeit)\n\"Der von den ewigen Gongschlägen enthusiastischer Krieger entnervte Zalas hat ihn tief in die Höhlen der Bleichborken verbracht.\"" }
entries[163746] = { ["name"] = "Altes Fläschchen", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses alte, abgewetzte Fläschchen ähnelt jenen auf den Bildern des Glutordens.\"" }
entries[163747] = { ["name"] = "Altes Messer", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses alte, abgewetzte Messer ähnelt jenen auf den Bildern des Glutordens.\"" }
entries[163748] = { ["name"] = "Alter Hut", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser alte, abgewetzte Hut ähnelt jenen auf den Bildern des Glutordens.\"" }
entries[163749] = { ["name"] = "Alte Armbrust", ["text"] = "Wird beim Aufheben gebunden\n\"Diese alte, abgewetzte Armbrust ähnelt jenen auf den Bildern des Glutordens.\"" }
entries[163750] = { ["name"] = "Kovorkkostüm", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verwandelt Euch, sodass Ihr wie (ein kleiner) Kovork ausseht. (1 Stunde Abklingzeit)" }
entries[163753] = { ["name"] = "Tiefgeschmiedeter Beschlag", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nBenutzen: Bringt den Beschlag an Eurer Rüstung an, was den erlittenen körperlichen Schaden 10 Min. lang um 30% verringert.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[163755] = { ["name"] = "Schmiedehammer", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nBenutzen: Zertrümmert die Rüstung des Ziels und erhöht seinen erlittenen körperlichen Schaden für 1 Min. um 100%.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[163759] = { ["name"] = "Hasenpfote", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nBenutzen: Ergreift das Amulett, das Eure Chance, von Gegnern entdeckt zu werden, 30 Min. lang verringert.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
